<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/config/database.php';require_once dirname(__DIR__,2).'/includes/auth.php';requireAdmin();$errors=[];$notice='';$edit=null;if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!verifyCsrfToken())$errors[]='Permintaan tidak valid.';else{$a=$_POST['action']??'';$id=(int)($_POST['rak_id']??0);if($a==='delete'&&$id){$s=$pdo->prepare('SELECT COUNT(*) FROM arsip WHERE rak_id=:id');$s->execute(['id'=>$id]);if((int)$s->fetchColumn())$errors[]='Rak masih digunakan arsip dan tidak dapat dihapus.';else{$pdo->prepare('DELETE FROM rak WHERE rak_id=:id')->execute(['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'DELETE');$notice='Rak berhasil dihapus.';}}if(in_array($a,['create','update'],true)){$v=['lemari_id'=>(int)($_POST['lemari_id']??0),'kode_rak'=>trim((string)($_POST['kode_rak']??'')),'nama_rak'=>trim((string)($_POST['nama_rak']??''))?:null,'keterangan'=>trim((string)($_POST['keterangan']??''))?:null];if(!$v['lemari_id']||$v['kode_rak']==='')$errors[]='Lemari dan kode rak wajib diisi.';$s=$pdo->prepare('SELECT lemari_id FROM lemari WHERE lemari_id=:id');$s->execute(['id'=>$v['lemari_id']]);if(!$s->fetch())$errors[]='Lemari tidak valid.';$s=$pdo->prepare('SELECT rak_id FROM rak WHERE lemari_id=:lemari_id AND kode_rak=:kode_rak AND rak_id!=:id');$s->execute(['lemari_id'=>$v['lemari_id'],'kode_rak'=>$v['kode_rak'],'id'=>$id]);if($s->fetch())$errors[]='Kode rak sudah digunakan pada lemari ini.';if(!$errors&&$a==='create'){$pdo->prepare('INSERT INTO rak(lemari_id,kode_rak,nama_rak,keterangan) VALUES(:lemari_id,:kode_rak,:nama_rak,:keterangan)')->execute($v);logActivity($pdo,(int)$_SESSION['user_id'],'CREATE');$notice='Rak berhasil ditambahkan.';}if(!$errors&&$a==='update'&&$id){$pdo->prepare('UPDATE rak SET lemari_id=:lemari_id,kode_rak=:kode_rak,nama_rak=:nama_rak,keterangan=:keterangan WHERE rak_id=:id')->execute($v+['id'=>$id]);logActivity($pdo,(int)$_SESSION['user_id'],'UPDATE');$notice='Rak berhasil diperbarui.';}}}}if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM rak WHERE rak_id=:id');$s->execute(['id'=>(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$parents=$pdo->query('SELECT l.lemari_id,l.kode_lemari,l.nama_lemari,r.nama_ruangan,u.nama_unit FROM lemari l JOIN ruangan r ON r.ruangan_id=l.ruangan_id JOIN unit_kerja u ON u.unit_id=r.unit_id ORDER BY u.nama_unit,r.nama_ruangan,l.kode_lemari')->fetchAll();$q=trim((string)($_GET['q']??''));$s=$pdo->prepare('SELECT k.*,l.nama_lemari,r.nama_ruangan,u.nama_unit,(SELECT COUNT(*) FROM arsip a WHERE a.rak_id=k.rak_id) archive_count FROM rak k JOIN lemari l ON l.lemari_id=k.lemari_id JOIN ruangan r ON r.ruangan_id=l.ruangan_id JOIN unit_kerja u ON u.unit_id=r.unit_id WHERE k.kode_rak LIKE :a OR COALESCE(k.nama_rak,\'\') LIKE :b ORDER BY u.nama_unit,r.nama_ruangan,l.kode_lemari,k.kode_rak');$s->execute(['a'=>"%$q%",'b'=>"%$q%"]);$items=$s->fetchAll();?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php require dirname(__DIR__,2).'/includes/favicon.php';?><title>Rak | e-ARSIP</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Material+Symbols+Outlined" rel="stylesheet"><link rel="stylesheet" href="../../assets/css/auth.css"></head><body class="dashboard-body"><aside class="admin-sidebar"><div class="brand"><img src="../../assets/images/logo_kai.svg" alt="KAI"><div><strong>e-ARSIP</strong><strong>KAI DIVRE III</strong></div></div><nav><p>Master Data</p><a href="unit.php">Unit Kerja</a><a href="ruangan.php">Ruangan</a><a href="lemari.php">Lemari</a><span class="nav-active">Rak</span></nav></aside><div class="admin-main"><header class="admin-header"><b>Rak</b><details class="user-menu"><summary><span class="user-avatar"><?=e(strtoupper(substr((string)($_SESSION['nama_lengkap'] ?? $_SESSION['username'] ?? 'U'),0,1)))?></span><span class="user-summary-text"><b><?=e((string)($_SESSION['nama_lengkap'] ?? $_SESSION['username'] ?? 'User'))?></b><small><?=e((string)($_SESSION['role_name'] ?? 'Admin'))?></small></span><i class="user-summary-chevron material-symbols-outlined">expand_more</i></summary><div class="user-dropdown"><div class="user-dropdown-header"><b><?=e((string)($_SESSION['nama_lengkap'] ?? $_SESSION['username'] ?? 'User'))?></b><small><?=e((string)($_SESSION['role_name'] ?? 'Admin'))?></small></div><a href="../../logout.php"><i class="material-symbols-outlined">logout</i>Logout</a></div></details></header><main class="admin-content"><?php if($notice):?><p class="notice"><?=e($notice)?></p><?php endif;if($errors):?><div class="alert"><?php foreach($errors as $e):?><div><?=e($e)?></div><?php endforeach;?></div><?php endif;?><section class="panel master-form"><h2><?=$edit?'Edit':'Tambah'?> Rak</h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="rak_id" value="<?=(int)$edit['rak_id']?>"><?php endif;?><label>Lemari<select name="lemari_id" required><option value="">Pilih lemari</option><?php foreach($parents as $p):?><option value="<?=(int)$p['lemari_id']?>" <?=((int)($edit['lemari_id']??0)===(int)$p['lemari_id'])?'selected':''?>><?=e($p['nama_unit'].' - '.$p['nama_ruangan'].' - '.$p['kode_lemari'])?></option><?php endforeach;?></select></label><label>Kode Rak<input name="kode_rak" required maxlength="50" value="<?=e($edit['kode_rak']??'')?>"></label><label>Nama Rak<input name="nama_rak" maxlength="100" value="<?=e($edit['nama_rak']??'')?>"></label><label>Keterangan<textarea name="keterangan" maxlength="255"><?=e($edit['keterangan']??'')?></textarea></label><div><button class="primary-button">Simpan</button></div></form></section><section class="panel user-list"><h2>Daftar Rak</h2><form class="filter-form"><input name="q" value="<?=e($q)?>" placeholder="Cari kode atau nama"><button>Cari</button></form><div class="table-wrap"><table><thead><tr><th>Unit</th><th>Ruangan</th><th>Lemari</th><th>Kode</th><th>Nama</th><th>Arsip</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['nama_unit'])?></td><td><?=e($x['nama_ruangan'])?></td><td><?=e($x['nama_lemari']??'-')?></td><td><?=e($x['kode_rak'])?></td><td><?=e($x['nama_rak']??'-')?></td><td><?=(int)$x['archive_count']?></td><td><a href="rak.php?edit=<?=(int)$x['rak_id']?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="rak_id" value="<?=(int)$x['rak_id']?>"><button>Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>